# Point-in-time retail evidence and explicitly typed economic relationships.
.cr_rf_text<-function(x,name){if(!is.character(x)||length(x)!=1L||is.na(x)||!nzchar(trimws(x))) .cr_error('RETAIL_CONTRACT',paste(name,'must be a nonempty string'));x}
