.cr_rf_number<-function(x,name,minimum=NULL){a<-.cr_numeric(x,name);if(length(a)!=1L||!is.null(dim(a))||(!is.null(minimum)&&a<minimum)) .cr_error('RETAIL_INPUT',paste(name,'requires a finite scalar in its domain'));as.numeric(a)}
.cr_rf_cutoffs<-function(as_of,information_cutoff,context=NULL){anchor<-.cr_data_date(as_of,'as_of');cutoff<-.cr_data_date(information_cutoff,'information_cutoff');if(cutoff>anchor) .cr_error('RETAIL_DATE','Feature information cutoff cannot follow its economic evaluation date');ctx<-.cr_result(NULL,'retail_features.context',context=context)$context;for(k in c('as_of','information_cutoff','known_at')){v<-if(k=='as_of')as_of else information_cutoff;if(!is.null(ctx[[k]])&&!identical(ctx[[k]],v)) .cr_error('TARGET_MISMATCH',paste('Context',k,'differs from feature cutoff'))};hashed<-!is.null(ctx$context_hash);ctx$context_hash<-NULL;ctx$mode<-'DATED';ctx$as_of<-as_of;ctx$known_at<-information_cutoff;if(hashed)ctx$context_hash<-.cr_hash(ctx);list(anchor=anchor,cutoff=cutoff,context=ctx)}
.cr_rf_sort<-function(rows,keys){if(!length(rows))return(rows);parts<-lapply(keys,function(k)vapply(rows,function(r)r[[k]],if(is.numeric(rows[[1]][[k]]))numeric(1)else character(1)));rows[do.call(order,c(parts,list(method='radix')))]}
.cr_rf_releases<-function(records,key,cutoff,name){rows<-.cr_data_rows(records,name);groups<-list();excluded<-list();seen<-character();for(i in seq_along(rows)){row<-rows[[i]];.cr_data_required(row,c(key,'release_seq','known_at'));.cr_rf_text(row[[key]],key);.cr_data_days(row$release_seq,'release_seq',1);identity<-.cr_data_key(row,c(key,'release_seq'));if(identity%in%seen) .cr_error('DATA_DUPLICATE','Duplicate logical record and release sequence');seen<-c(seen,identity);known<-.cr_data_date(row$known_at,'known_at');if(known>cutoff){excluded[[length(excluded)+1L]]<-list(record_id=row[[key]],release_seq=row$release_seq,reason='NOT_YET_KNOWN');next};previous<-groups[[row[[key]]]];if(is.null(previous)||row$known_at>rows[[previous]]$known_at||(row$known_at==rows[[previous]]$known_at&&row$release_seq>rows[[previous]]$release_seq))groups[[row[[key]]]]<-i}
