.cr_rf_coverage<-function(coverage,cutoff){if(!.cr_object(coverage)) .cr_error('RETAIL_COVERAGE','Explicit source coverage object required');.cr_data_required(coverage,c('status','sources','known_at'));if(!(coverage$status%in%c('COMPLETE','PARTIAL','UNKNOWN'))||.cr_data_date(coverage$known_at,'coverage.known_at')>cutoff) .cr_error('RETAIL_COVERAGE','Coverage must be known at cutoff and COMPLETE/PARTIAL/UNKNOWN');sources<-.cr_rf_strings(coverage$sources,'coverage.sources');if(coverage$status=='COMPLETE'&&!length(sources)) .cr_error('RETAIL_COVERAGE','Complete coverage needs at least one named source');coverage$sources<-as.list(sources);coverage}
.cr_rf_bound<-function(value){value$artifact_hash<-.cr_hash(value);value}
.cr_rf_artifact<-function(value,kind){if(inherits(value,'CalcResult'))value<-value$value;if(!.cr_object(value)||!identical(value$artifact_type,kind)||!identical(value$schema_version,'1.0')) .cr_error('RETAIL_ARTIFACT',paste('Expected',kind,'artifact'));raw<-value;digest<-raw$artifact_hash;raw$artifact_hash<-NULL;if(!identical(digest,.cr_hash(raw))) .cr_error('INTEGRITY_ERROR','Retail artifact differs from its frozen content');value}

validate_retail_dataset<-function(tables,data_contract,as_of,information_cutoff,context=NULL){times<-.cr_rf_cutoffs(as_of,information_cutoff,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;if(!.cr_object(tables)||!.cr_object(data_contract)||!identical(data_contract$schema_version,'1.0')) .cr_error('RETAIL_CONTRACT','Named local tables and version1.0 RetailDataContract required');.cr_data_required(data_contract,c('contract_id','version','table_specs','prohibited_feature_fields','source_coverage'));.cr_rf_text(data_contract$version,'version');specs<-.cr_data_rows(data_contract$table_specs,'table_specs');.cr_data_unique(specs,'table','table_specs');forbidden<-union(.cr_rf_strings(data_contract$prohibited_feature_fields,'prohibited_feature_fields'),c('target','outcome','label','default_in_horizon','future_default','lgd_target','recovery_target'));known_specs<-setNames(specs,vapply(specs,`[[`,character(1),'table'));issues<-list();data<-eligible<-list();coverage<-list();issue<-function(table,index,code,field){issues[[length(issues)+1L]]<<-list(table=table,row_index=index,code=code,field=field)}
