  name<-spec$table;data[[name]]<-.cr_data_rows(if(is.null(tables[[name]]))list()else tables[[name]],name);eligible[[name]]<-integer();if(!(name%in%names(tables)))issue(name,NULL,'MISSING_TABLE',NULL);if(spec$role!='FEATURE'&&length(features)) .cr_error('RETAIL_CONTRACT','Only FEATURE-role tables can designate model features');if(any(features%in%forbidden))issue(name,NULL,'OUTCOME_AS_FEATURE',paste(sort(intersect(features,forbidden)),collapse=','));seen<-character()
  for(i in seq_along(data[[name]])){row<-data[[name]][[i]];valid_fields<-character();for(field in fields){key<-field$name;value<-row[[key]];kind<-field$type;if(!(key%in%names(row))||is.null(value)||(length(value)==1L&&is.atomic(value)&&is.na(value))){if(!field$nullable||key%in%keys)issue(name,i-1L,'MISSING_REQUIRED',key);next};valid<-FALSE;if(kind=='string')valid<-is.character(value)&&length(value)==1L&&nzchar(value)else if(kind=='boolean')valid<-is.logical(value)&&length(value)==1L else if(kind%in%c('number','integer'))valid<-is.numeric(value)&&length(value)==1L&&is.finite(value)&&(kind!='integer'||value==floor(value))else if(kind=='date')valid<-tryCatch({.cr_data_date(value,key);TRUE},error=function(e)FALSE);if(!valid)issue(name,i-1L,'INVALID_TYPE',key)else valid_fields<-c(valid_fields,key)}
   if(!spec$allow_extra_fields)for(key in sort(setdiff(names(row),names(fieldmap))))issue(name,i-1L,'UNDECLARED_FIELD',key);if(all(keys%in%valid_fields)){key<-.cr_data_key(row,keys);if(key%in%seen)issue(name,i-1L,'DUPLICATE_KEY',paste(keys,collapse=','));seen<-c(seen,key)}
   for(pair in spec$date_order){pair<-unlist(pair,use.names=FALSE);if(!is.character(pair)||length(pair)!=2L||any(!(pair%in%names(fieldmap)))||any(vapply(pair,function(k)fieldmap[[k]]$type!='date',logical(1)))) .cr_error('RETAIL_CONTRACT','date_order requires declared date-field pairs');if(all(pair%in%valid_fields)&&row[[pair[1]]]>row[[pair[2]]])issue(name,i-1L,'DATE_ORDER',paste(pair,collapse=','))}
   ef<-spec$event_field;kf<-spec$known_field;if(ef%in%valid_fields&&kf%in%valid_fields&&.cr_data_date(row[[ef]],ef)<=anchor&&.cr_data_date(row[[kf]],kf)<=cutoff)eligible[[name]]<-c(eligible[[name]],i-1L)
  }
