  for(i in seq_along(data[[name]])){value<-data[[name]][[i]][[fk$field]];if(is.null(value))next;if(!atomic_key(value)||!contains(ids,value))issue(name,i-1L,'FOREIGN_KEY',fk$field)else if((i-1L)%in%eligible[[name]]&&!contains(visible_ids,value))issue(name,i-1L,'PARENT_NOT_KNOWN_AT_CUTOFF',fk$field)}
 }}
 source_rows<-.cr_data_rows(data_contract$source_coverage,'source_coverage');.cr_data_unique(source_rows,'source_id','source_coverage');for(source in source_rows){.cr_data_required(source,c('source_id','status','known_at'));if(!(source$status%in%c('COMPLETE','PARTIAL','UNKNOWN'))) .cr_error('RETAIL_COVERAGE','Source status must be COMPLETE/PARTIAL/UNKNOWN');coverage[[length(coverage)+1L]]<-list(source_id=source$source_id,status=if(.cr_data_date(source$known_at,'known_at')<=cutoff)source$status else 'UNKNOWN')};counts<-setNames(lapply(sort(names(data)),function(k)length(data[[k]])),sort(names(data)));elig<-setNames(lapply(sort(names(eligible)),function(k)as.list(eligible[[k]])),sort(names(eligible)));if(!length(counts))counts<-.cr_empty_object();if(!length(elig))elig<-.cr_empty_object()
 .cr_result(list(valid=!length(issues),applicability='APPLICABLE',violations=issues,row_counts=counts,eligible_row_indices=elig,source_coverage=.cr_rf_sort(coverage,'source_id')),'retail_features.validate_retail_dataset','data_validation',ctx,diagnostics=list(contract_fingerprint=.cr_hash(data_contract),as_of=as_of,information_cutoff=information_cutoff),limitations=list('Schema and point-in-time relational checks do not validate predictive usefulness, lawful feature use or completeness of unreported sources. Unknown coverage is not evidence of zero obligations.'))}

build_customer_household_graph<-function(entities,relationships,as_of,information_cutoff,context=NULL){times<-.cr_rf_cutoffs(as_of,information_cutoff,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;nodes<-.cr_data_rows(entities,'entities');.cr_data_unique(nodes,'entity_id','entities');lookup<-list();visible<-list()
 for(row in nodes){.cr_data_required(row,c('entity_type','known_at'));if(!(row$entity_type%in%c('CUSTOMER','HOUSEHOLD','APPLICATION','FACILITY','BUSINESS'))) .cr_error('RETAIL_ENTITY','Unknown entity type');lookup[[row$entity_id]]<-row;if(.cr_data_date(row$known_at,'entity.known_at')<=cutoff)visible[[length(visible)+1L]]<-row}
 release<-.cr_rf_releases(relationships,'relationship_id',cutoff,'relationships');selected<-release$rows;excluded<-release$excluded;edges<-list();members<-list();seen<-character();budget<-list();types<-c(MEMBER_OF='HOUSEHOLD',COAPPLICANT_ON='APPLICATION',BORROWER_ON='FACILITY',GUARANTOR_ON='FACILITY',OWNER_OF='BUSINESS')
 for(row in selected){.cr_data_required(row,c('source_id','target_id','role','effective_from','evidence_reference'));.cr_rf_text(row$evidence_reference,'evidence_reference');if(!all(c('effective_until','liability_fraction','budget_share')%in%names(row))) .cr_error('RETAIL_CONTRACT','Explicit nullable end date, liability fraction and budget share required');start<-.cr_data_date(row$effective_from,'effective_from');end<-if(is.null(row$effective_until))NULL else .cr_data_date(row$effective_until,'effective_until');if(!is.null(end)&&end<=start) .cr_error('RETAIL_DATE','Relationship uses nonempty [effective_from,effective_until) interval');if(start>anchor||(!is.null(end)&&anchor>=end)){excluded[[length(excluded)+1L]]<-list(record_id=row$relationship_id,release_seq=row$release_seq,reason='OUTSIDE_EFFECTIVE_INTERVAL');next};source<-lookup[[row$source_id]];target<-lookup[[row$target_id]];role<-row$role
  if(!(role%in%names(types))||is.null(source)||is.null(target)||source$entity_type!='CUSTOMER'||target$entity_type!=types[[role]]) .cr_error('RETAIL_ENTITY','Relationship role endpoints have incompatible entity types');if(.cr_data_date(source$known_at,'source.known_at')>cutoff||.cr_data_date(target$known_at,'target.known_at')>cutoff) .cr_error('RETAIL_DATE','Visible relationship references an entity not known at cutoff');key<-.cr_data_key(row,c('source_id','target_id','role'));if(key%in%seen) .cr_error('DOUBLE_COUNTING','Duplicate active person/target/role relationship');seen<-c(seen,key)
  for(field in c('liability_fraction','budget_share'))if(!is.null(row[[field]])){v<-.cr_rf_number(row[[field]],field);if(v<0||v>1) .cr_error('RETAIL_LIABILITY','Fractions must be in [0,1]')};if(!(role%in%c('BORROWER_ON','GUARANTOR_ON'))&&(!is.null(row$liability_fraction)||!is.null(row$budget_share))) .cr_error('RETAIL_LIABILITY','Debt fractions belong to borrower or guarantor roles only');if(role=='MEMBER_OF'){if(!is.null(members[[row$source_id]])) .cr_error('RETAIL_MEMBERSHIP','A customer needs a unique active economic household at this snapshot');members[[row$source_id]]<-row$target_id};if(role=='BORROWER_ON'&&!is.null(row$budget_share))budget[[row$target_id]]<-c(budget[[row$target_id]],row$budget_share);edges[[length(edges)+1L]]<-row
 }
 if(any(vapply(budget,function(v).cr_loss_sum(v)>1,logical(1)))) .cr_error('RETAIL_LIABILITY','Internal borrower budget shares may not sum above one; legal joint liability is separate');paths<-lapply(Filter(function(r)r$role%in%c('BORROWER_ON','GUARANTOR_ON'),edges),function(r)list(customer_id=r$source_id,household_id=members[[r$source_id]],facility_id=r$target_id,role=r$role,liability_fraction=r$liability_fraction,budget_share=r$budget_share,relationship_id=r$relationship_id));value<-.cr_rf_bound(list(schema_version='1.0',artifact_type='RETAIL_RELATIONSHIP_GRAPH',as_of=as_of,information_cutoff=information_cutoff,entities=.cr_rf_sort(visible,'entity_id'),relationships=.cr_rf_sort(edges,'relationship_id'),memberships=lapply(sort(names(members)),function(k)list(customer_id=k,household_id=members[[k]])),liability_paths=.cr_rf_sort(paths,c('customer_id','facility_id','role'))))
 .cr_result(value,'retail_features.build_customer_household_graph','typed_graph',ctx,diagnostics=list(excluded_releases=.cr_rf_sort(excluded,c('record_id','release_seq'))),limitations=list('Identity is supplied through typed keys, never inferred from address or name. A household is economic context, not an automatic legal default unit. Legal liability fractions can each equal one for joint borrowers; internal budget shares cannot be added as legal liability.'))}

aggregate_household_obligations<-function(obligations,household_graph,coverage,currency,period,guarantee_budget_policy,context=NULL){graph<-.cr_rf_artifact(household_graph,'RETAIL_RELATIONSHIP_GRAPH');times<-.cr_rf_cutoffs(graph$as_of,graph$information_cutoff,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;coverage<-.cr_rf_coverage(coverage,cutoff);.cr_rf_text(currency,'currency');.cr_rf_text(period,'period');if(!is.null(ctx$currency)&&ctx$currency!=currency) .cr_error('TARGET_MISMATCH','Context currency differs from obligations');if(!(guarantee_budget_policy%in%c('exclude','include_declared_share'))) .cr_error('RETAIL_LIABILITY','Explicit guarantee budget inclusion policy required');release<-.cr_rf_releases(obligations,'facility_id',cutoff,'obligations');rows<-release$rows;excluded<-release$excluded;facilities<-vapply(Filter(function(r)r$entity_type=='FACILITY',graph$entities),`[[`,character(1),'entity_id');values<-list();lineage<-list()
 for(row in rows){.cr_data_required(row,c('source_id','observed_at','currency','period','status'));if(!all(c('debt_stock','scheduled_debt_service')%in%names(row))) .cr_error('RETAIL_CONTRACT','Debt and service require explicit value or null');observed<-.cr_data_date(row$observed_at,'observed_at');if(observed>.cr_data_date(row$known_at,'known_at')) .cr_error('RETAIL_DATE','Historical obligation snapshot cannot be known before observation');if(observed>anchor)next;if(!(row$facility_id%in%facilities)) .cr_error('RETAIL_ENTITY','Obligation has no visible facility in supplied graph');if(row$currency!=currency||row$period!=period) .cr_error('TARGET_MISMATCH','Obligation currency and debt-service period must match');if(!(row$source_id%in%unlist(coverage$sources))) .cr_error('RETAIL_COVERAGE','Obligation source not declared in coverage');if(!(row$status%in%c('ACTIVE','CLOSED','UNKNOWN'))) .cr_error('RETAIL_CONTRACT','Declare obligation ACTIVE/CLOSED/UNKNOWN status');for(key in c('debt_stock','scheduled_debt_service')){if(!is.null(row[[key]])) .cr_rf_number(row[[key]],key,0);if(row$status=='CLOSED'&&(is.null(row[[key]])||row[[key]]!=0)) .cr_error('RETAIL_CONTRACT','Closed obligations require explicit zero residual amounts')};values[[row$facility_id]]<-row;lineage[[length(lineage)+1L]]<-list(facility_id=row$facility_id,release_seq=row$release_seq,source_id=row$source_id,age_days=as.numeric(anchor-observed))}
 outputs<-person_rows<-list();for(node in .cr_rf_sort(graph$entities,'entity_id')){if(node$entity_type!='HOUSEHOLD')next;hid<-node$entity_id;members<-vapply(Filter(function(r)identical(r$household_id,hid),graph$memberships),`[[`,character(1),'customer_id');paths<-Filter(function(r)identical(r$household_id,hid),graph$liability_paths);selected_paths<-Filter(function(r)r$role=='BORROWER_ON'||guarantee_budget_policy=='include_declared_share',paths);ids<-sort(unique(vapply(selected_paths,`[[`,character(1),'facility_id')));known_stock<-known_service<-budget_stock<-budget_service<-numeric();uncertain<-uncertain_stock<-uncertain_service<-unknown_budget<-character()
  for(fid in ids){row<-values[[fid]];selected<-Filter(function(r)r$facility_id==fid&&(r$role=='BORROWER_ON'||guarantee_budget_policy=='include_declared_share'),paths);if(is.null(row)||row$status=='UNKNOWN'||is.null(row$debt_stock))uncertain_stock<-c(uncertain_stock,fid);if(is.null(row)||row$status=='UNKNOWN'||is.null(row$scheduled_debt_service))uncertain_service<-c(uncertain_service,fid);if(fid%in%union(uncertain_stock,uncertain_service))uncertain<-c(uncertain,fid);if(!is.null(row)){if(!is.null(row$debt_stock))known_stock<-c(known_stock,row$debt_stock);if(!is.null(row$scheduled_debt_service))known_service<-c(known_service,row$scheduled_debt_service)};if(is.null(row)||any(vapply(selected,function(r)is.null(r$budget_share),logical(1)))){unknown_budget<-c(unknown_budget,fid);next};share<-.cr_loss_sum(vapply(selected,`[[`,numeric(1),'budget_share'));if(share>1) .cr_error('DOUBLE_COUNTING','Selected borrower/guarantee budget shares exceed one for household facility');if(!is.null(row$debt_stock))budget_stock<-c(budget_stock,.cr_loss_multiply(share,row$debt_stock));if(!is.null(row$scheduled_debt_service))budget_service<-c(budget_service,.cr_loss_multiply(share,row$scheduled_debt_service))}
  stock_complete<-coverage$status=='COMPLETE'&&!length(uncertain_stock);service_complete<-coverage$status=='COMPLETE'&&!length(uncertain_service);outputs[[length(outputs)+1L]]<-list(household_id=hid,customer_ids=as.list(sort(members)),facility_ids=as.list(ids),known_linked_debt_stock=.cr_loss_sum(known_stock),known_linked_debt_service=.cr_loss_sum(known_service),total_linked_debt_stock=if(stock_complete).cr_loss_sum(known_stock)else NULL,total_linked_debt_service=if(service_complete).cr_loss_sum(known_service)else NULL,known_budget_debt_stock=.cr_loss_sum(budget_stock),known_budget_debt_service=.cr_loss_sum(budget_service),total_budget_debt_stock=if(stock_complete&&!length(unknown_budget)).cr_loss_sum(budget_stock)else NULL,total_budget_debt_service=if(service_complete&&!length(unknown_budget)).cr_loss_sum(budget_service)else NULL,uncertain_facility_ids=as.list(uncertain),uncertain_stock_facility_ids=as.list(uncertain_stock),uncertain_service_facility_ids=as.list(uncertain_service),unknown_budget_share_facility_ids=as.list(unknown_budget),coverage_status=coverage$status)
 }
 for(path in graph$liability_paths){row<-values[[path$facility_id]];fraction<-path$liability_fraction;person_rows[[length(person_rows)+1L]]<-list(customer_id=path$customer_id,facility_id=path$facility_id,role=path$role,legal_debt_stock=if(is.null(row)||is.null(row$debt_stock)||is.null(fraction))NULL else .cr_loss_multiply(row$debt_stock,fraction),legal_debt_service=if(is.null(row)||is.null(row$scheduled_debt_service)||is.null(fraction))NULL else .cr_loss_multiply(row$scheduled_debt_service,fraction))}
