.cr_rf_mapped_rows<-function(records,mapping,fields,name){if(!is.list(mapping)||(length(mapping)&&is.null(names(mapping)))||any(!names(mapping)%in%fields)||any(!vapply(mapping,function(v)is.character(v)&&length(v)==1&&!is.na(v)&&nzchar(v),logical(1)))) .cr_error('RETAIL_MAPPING','Mapping keys must be supported canonical fields and values source field names');lapply(.cr_data_rows(records,name),function(row){sources<-vapply(fields,function(k)if(is.null(mapping[[k]]))k else mapping[[k]],character(1));if(any(!sources%in%names(row))) .cr_error('RETAIL_MAPPING',paste('Missing mapped',name,'field; nullable values must be explicit'));setNames(lapply(sources,function(k)row[[k]]),fields)})}

