build_thin_file_features<-function(bureau_features,evidence,eligibility_profile,customer_id,as_of,information_cutoff,context=NULL){times<-.cr_rf_cutoffs(as_of,information_cutoff,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;.cr_rf_text(customer_id,'customer_id');if(inherits(bureau_features,'CalcResult')){if(bureau_features$method_id!='retail_features.build_bureau_features') .cr_error('RETAIL_EVIDENCE','Expected bureau feature result');bureau_features<-bureau_features$value};if(!.cr_object(bureau_features)||!identical(bureau_features$customer_id,customer_id)||!identical(bureau_features$as_of,as_of)||!identical(bureau_features$information_cutoff,information_cutoff)) .cr_error('RETAIL_EVIDENCE','Bureau customer and information snapshot must match');profile<-eligibility_profile;if(!.cr_object(profile)) .cr_error('RETAIL_CONTRACT','Explicit dated feature eligibility profile required');.cr_data_required(profile,c('profile_id','version','known_at','minimum_tradelines','minimum_history_days','maximum_evidence_age_days','allow_partial_evidence','feature_requirements'));if(.cr_data_date(profile$known_at,'profile.known_at')>cutoff||!is.logical(profile$allow_partial_evidence)||length(profile$allow_partial_evidence)!=1||is.na(profile$allow_partial_evidence)) .cr_error('RETAIL_DATE','Eligibility profile unavailable or partial-evidence policy invalid');minimum<-.cr_data_days(profile$minimum_tradelines,'minimum_tradelines');history<-.cr_data_days(profile$minimum_history_days,'minimum_history_days');max_age<-.cr_data_days(profile$maximum_evidence_age_days,'maximum_evidence_age_days');state<-bureau_features$file_state;features<-bureau_features$features;if(!is.list(features)||is.null(bureau_features$coverage_status)||!(bureau_features$coverage_status%in%c('UNKNOWN','COMPLETE','PARTIAL','NO_HIT'))) .cr_error('RETAIL_EVIDENCE','Bureau feature dictionary and coverage required');for(field in c('reported_tradeline_count','history_days'))if(!is.null(features[[field]]