reconcile_income_evidence<-function(declarations,documentary_evidence,transaction_evidence,inclusion_policy,customer_id,as_of,information_cutoff,currency,period,basis,context=NULL){times<-.cr_rf_cutoffs(as_of,information_cutoff,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;.cr_rf_text(customer_id,'customer_id');.cr_rf_text(currency,'currency');.cr_rf_text(period,'period');if(!is.null(ctx$currency)&&ctx$currency!=currency) .cr_error('TARGET_MISMATCH','Context currency differs from income reporting currency');if(!(basis%in%c('NET','GROSS'))) .cr_error('RETAIL_INCOME','Explicit NET or GROSS target basis required');policy<-inclusion_policy;if(!.cr_object(policy)) .cr_error('RETAIL_CONTRACT','Explicit dated income inclusion policy required');.cr_data_required(policy,c('policy_id','version','known_at','source_priority','included_component_types','expected_component_ids','coverage_status','maximum_age_days','allow_stale','relative_discrepancy_threshold'));if(.cr_data_date(policy$known_at,'policy.known_at')>cutoff||!is.logical(policy$allow_stale)||length(policy$allow_stale)!=1||is.na(policy$allow_stale)) .cr_error('RETAIL_DATE','Income policy unavailable or stale-evidence policy invalid');priority<-.cr_rf_strings(policy$source_priority,'source_priority',FALSE);if(!setequal(priority,c('DECLARED','DOCUMENT','TRANSACTION'))) .cr_error('RETAIL_INCOME','Prioritize each declared/document/transaction source once');included<-.cr_rf_strings(policy$included_component_types,'included_component_types');allowed<-c('SALARY','BONUS','PENSION','RENT_NET','NET_BUSINESS_INCOME','OTHER_NET_INCOME');if(any(!included%in%allowed)||!(policy$coverage_status%in%c('COMPLETE','PARTIAL','UNKNOWN'))) .cr_error('RETAIL_INCOME','Explicit income component types and source coverage required; revenue is not income');expected<-.cr_rf_strings(policy$expected_component_ids,'expected_component_ids');max_age<-.cr_data_days(policy$maximum_age_days,'maximum_age_days');threshold<-.cr_rf_numb